<?php
require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();oecrm_require_csrf();oecrm_require_permission($conn,'project_sprints','manage');$companyId=oecrm_current_company_id($conn);$actor=(int)$_SESSION['adminId'];$action=$_POST['action']??'';
if($action==='create'){$project=(int)$_POST['project_id'];$valid=mysqli_fetch_assoc(mysqli_query($conn,'SELECT id FROM projectstbl WHERE id='.$project.' AND company_id='.$companyId));if(!$valid)exit('Invalid project.');$name=trim($_POST['name']);$goal=trim($_POST['goal']);$start=$_POST['start_date'];$end=$_POST['end_date'];$s=mysqli_prepare($conn,'INSERT INTO project_sprints(project_id,name,goal,start_date,end_date,created_by) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'issssi',$project,$name,$goal,$start,$end,$actor);mysqli_stmt_execute($s);oecrm_audit($conn,'project_sprints','create','sprint',mysqli_insert_id($conn),'Sprint created');header('Location: sprints.php?project_id='.$project);exit;}
if($action==='assign_task'){$task=(int)$_POST['task_id'];$sprint=(int)$_POST['sprint_id'];mysqli_query($conn,"UPDATE tasktbl t JOIN projectstbl p ON p.id=CAST(t.projectId AS UNSIGNED) SET t.sprint_id=".($sprint?:'NULL')." WHERE t.id=$task AND p.company_id=$companyId");oecrm_audit($conn,'project_sprints','assign','task',$task,'Task assigned to sprint',null,['sprint_id'=>$sprint]);header('Location: projectKanban.php?project_id='.(int)$_POST['project_id']);}
